import React, { useEffect, useMemo, useState } from 'react';
import { Helmet } from 'react-helmet';

import { css } from '@emotion/react';
import { format, parseISO } from 'date-fns';

import { Footer } from '../components/Footer';
import SiteNav from '../components/header/SiteNav';
import { Wrapper } from '../components/Wrapper';
import IndexLayout from '../layouts';
import {
  inner,
  outer,
  SiteArchiveHeader,
  SiteHeader,
  SiteMain,
  SiteNavMain,
} from '../styles/shared';
import { NoImage, PostFull, PostFullHeader, PostFullTitle } from '../templates/post';
import { colors } from '../styles/colors';

// The video list ships only as ciphertext (see scripts/encrypt-recaps.js) and is
// decrypted here in the browser with the community password.
const DATA_URL = '/recaps-data.json';
const REMEMBER_KEY = 'recaps-password';

type RecapEvent = {
  name: string;
  date: string;
  dateApprox?: boolean;
  location?: string;
};

type Recap = {
  id: string;
  teachers: string[];
  event: string;
  topic: string;
  tags: string[];
  recorded: string;
};

type RecapData = {
  events: RecapEvent[];
  videos: Recap[];
};

type Encrypted = {
  iterations: number;
  salt: string;
  iv: string;
  data: string;
};

const fromBase64 = (value: string) => Uint8Array.from(atob(value), c => c.charCodeAt(0));

async function decrypt(encrypted: Encrypted, password: string): Promise<RecapData> {
  const { subtle } = window.crypto;
  const baseKey = await subtle.importKey(
    'raw',
    new TextEncoder().encode(password),
    'PBKDF2',
    false,
    ['deriveKey'],
  );
  const key = await subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt: fromBase64(encrypted.salt),
      iterations: encrypted.iterations,
      hash: 'SHA-256',
    },
    baseKey,
    { name: 'AES-GCM', length: 256 },
    false,
    ['decrypt'],
  );
  const plaintext = await subtle.decrypt(
    { name: 'AES-GCM', iv: fromBase64(encrypted.iv) },
    key,
    fromBase64(encrypted.data),
  );
  return JSON.parse(new TextDecoder().decode(plaintext));
}

const fold = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase();

function eventDate(event?: RecapEvent) {
  if (!event?.date) {
    return '';
  }

  return format(parseISO(event.date), event.dateApprox ? 'yyyy' : 'MMMM yyyy');
}

function readQuery() {
  return new URLSearchParams(window.location.search).get('q') ?? '';
}

function writeQuery(query: string) {
  const url = new URL(window.location.href);
  if (query) {
    url.searchParams.set('q', query);
  } else {
    url.searchParams.delete('q');
  }

  window.history.replaceState(null, '', url.toString());
}

function rememberedPassword() {
  try {
    return window.localStorage.getItem(REMEMBER_KEY) ?? '';
  } catch {
    return '';
  }
}

function remember(password: string | undefined) {
  try {
    if (password) {
      window.localStorage.setItem(REMEMBER_KEY, password);
    } else {
      window.localStorage.removeItem(REMEMBER_KEY);
    }
  } catch {
    // Storage blocked (private window etc.); just ask again next visit.
  }
}

function Recaps() {
  const [data, setData] = useState<RecapData>();
  const [password, setPassword] = useState('');
  const [keep, setKeep] = useState(true);
  const [status, setStatus] = useState<'idle' | 'working' | 'wrong' | 'error'>('idle');
  const [query, setQuery] = useState('');

  const unlock = async (attempt: string, fromStorage = false) => {
    setStatus('working');
    try {
      const response = await fetch(DATA_URL);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const encrypted: Encrypted = await response.json();
      let result: RecapData;
      try {
        result = await decrypt(encrypted, attempt);
      } catch {
        if (fromStorage) {
          remember(undefined);
          setStatus('idle');
        } else {
          setStatus('wrong');
        }

        return;
      }

      if (!fromStorage) {
        remember(keep ? attempt : undefined);
      }

      setQuery(readQuery());
      setData(result);
      setStatus('idle');
    } catch {
      setStatus('error');
    }
  };

  useEffect(() => {
    const saved = rememberedPassword();
    if (saved) {
      void unlock(saved, true);
    }
    // Only on first load: try a remembered password once.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const search = (value: string) => {
    setQuery(value);
    writeQuery(value);
  };

  const groups = useMemo(() => {
    if (!data) {
      return [];
    }

    const events = new Map(data.events.map(e => [e.name, e]));
    const words = fold(query).split(/\s+/).filter(Boolean);
    const matches = data.videos.filter(v => {
      const event = events.get(v.event);
      const haystack = fold(
        [...v.teachers, v.event, event?.location ?? '', v.topic, ...v.tags].join(' '),
      );
      return words.every(word => haystack.includes(word));
    });

    const byEvent = new Map<string, Recap[]>();
    for (const video of matches) {
      byEvent.set(video.event, [...(byEvent.get(video.event) ?? []), video]);
    }

    return [...byEvent.entries()]
      .map(([name, videos]) => ({ name, event: events.get(name), videos }))
      .sort((a, b) => (b.event?.date ?? '').localeCompare(a.event?.date ?? ''));
  }, [data, query]);

  const total = groups.reduce((sum, group) => sum + group.videos.length, 0);

  return (
    <IndexLayout>
      <Helmet>
        <title>WCS recaps</title>
        <meta name="robots" content="noindex, nofollow, noarchive" />
      </Helmet>
      <Wrapper css={PageTemplate}>
        <header className="site-archive-header no-image" css={[SiteHeader, SiteArchiveHeader]}>
          <div css={[outer, SiteNavMain]}>
            <div css={inner}>
              <SiteNav isHome={false} />
            </div>
          </div>
        </header>
        <main id="site-main" className="site-main" css={[SiteMain, outer]}>
          <div css={inner}>
            <article className="post page" css={[PostFull, NoImage]}>
              <PostFullHeader className="post-full-header">
                <PostFullTitle className="post-full-title">West Coast Swing recaps</PostFullTitle>
              </PostFullHeader>

              {data ? (
                <div css={RecapsBody}>
                  <div className="recaps-search">
                    <input
                      type="search"
                      value={query}
                      placeholder="Search teacher, event or topic"
                      aria-label="Search recaps"
                      onChange={e => search(e.target.value)}
                    />
                    <p className="recaps-count">
                      {query
                        ? `${total} of ${data.videos.length} recaps match “${query}”`
                        : `${data.videos.length} recaps from ${groups.length} events`}
                      {query && (
                        <button type="button" className="recaps-link" onClick={() => search('')}>
                          Clear
                        </button>
                      )}
                    </p>
                  </div>

                  {groups.map(group => (
                    <section key={group.name} className="recaps-event">
                      <h2>
                        <button
                          type="button"
                          className="recaps-link"
                          onClick={() => search(group.name)}
                        >
                          {group.name}
                        </button>
                      </h2>
                      <p className="recaps-event-meta">
                        {[eventDate(group.event), group.event?.location]
                          .filter(Boolean)
                          .join(' · ')}
                        {' · '}
                        {group.videos.length} {group.videos.length === 1 ? 'recap' : 'recaps'}
                      </p>
                      <ul className="recaps-grid">
                        {group.videos.map(video => (
                          <li key={video.id} className="recaps-card">
                            <a href={`https://youtu.be/${video.id}`} target="_blank" rel="noreferrer">
                              <img
                                src={`https://i.ytimg.com/vi/${video.id}/mqdefault.jpg`}
                                alt=""
                                loading="lazy"
                                width={320}
                                height={180}
                              />
                              <span className="recaps-topic">{video.topic}</span>
                            </a>
                            <span className="recaps-teachers">
                              {video.teachers.map((teacher, i) => (
                                <React.Fragment key={teacher}>
                                  {i > 0 && ' + '}
                                  <button
                                    type="button"
                                    className="recaps-link"
                                    onClick={() => search(teacher)}
                                  >
                                    {teacher}
                                  </button>
                                </React.Fragment>
                              ))}
                            </span>
                          </li>
                        ))}
                      </ul>
                    </section>
                  ))}
                </div>
              ) : (
                <form
                  css={LockForm}
                  onSubmit={e => {
                    e.preventDefault();
                    void unlock(password);
                  }}
                >
                  <p>These recaps are shared with my dance community. Enter the password to view them.</p>
                  <input
                    type="password"
                    value={password}
                    autoComplete="current-password"
                    aria-label="Password"
                    placeholder="Password"
                    onChange={e => {
                      setPassword(e.target.value);
                      setStatus('idle');
                    }}
                  />
                  <label>
                    <input type="checkbox" checked={keep} onChange={e => setKeep(e.target.checked)} />
                    <span>Remember on this device</span>
                  </label>
                  <button type="submit" disabled={!password || status === 'working'}>
                    {status === 'working' ? 'Unlocking…' : 'Unlock'}
                  </button>
                  {status === 'wrong' && <p className="lock-message">That password didn’t work.</p>}
                  {status === 'error' && (
                    <p className="lock-message">Couldn’t load the recaps. Please try again later.</p>
                  )}
                </form>
              )}
            </article>
          </div>
        </main>
        <Footer />
      </Wrapper>
    </IndexLayout>
  );
}

